package com.emos.web;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.time.*;
@RestController @ConditionalOnProperty(name="emos.persistence.enabled",havingValue="true",matchIfMissing=true)
public class TrialMetricsController{
 private final JdbcTemplate jdbc;public TrialMetricsController(JdbcTemplate j){jdbc=j;}
 @GetMapping("/api/trial-metrics") Metrics get(@RequestParam LocalDate from,@RequestParam LocalDate to){var start=from.atStartOfDay(ZoneOffset.UTC).toInstant();var end=to.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();var seconds=jdbc.queryForObject("select coalesce(sum(active_seconds),0) from interaction_session where started_at>=? and started_at<?",Long.class,java.sql.Timestamp.from(start),java.sql.Timestamp.from(end));var days=Math.max(1,java.time.temporal.ChronoUnit.DAYS.between(from,to)+1);var resolved=jdbc.queryForObject("select count(*) from operational_alert where status='RESOLVED' and resolved_at>=? and resolved_at<?",Integer.class,java.sql.Timestamp.from(start),java.sql.Timestamp.from(end));var dispositioned=jdbc.queryForObject("select count(distinct subject_case_id) from disposition_obligation where expectation_key='operational-case-disposition' and source_resolved_at>=? and source_resolved_at<? and state='SATISFIED'",Integer.class,java.sql.Timestamp.from(start),java.sql.Timestamp.from(end));var within=jdbc.queryForObject("select count(*) from disposition_obligation where expectation_key='operational-case-disposition' and source_resolved_at>=? and source_resolved_at<? and state='SATISFIED' and satisfied_at<=deadline",Integer.class,java.sql.Timestamp.from(start),java.sql.Timestamp.from(end));return new Metrics(120,30,Math.round(seconds/60.0/days),resolved,dispositioned,percent(dispositioned,resolved),percent(within,dispositioned));}
 private static int percent(int n,int d){return d==0?0:(int)Math.round(n*100.0/d);}record Metrics(int baselineMinutesPerDay,int targetMinutesPerDay,long actualAverageMinutesPerDay,int resolvedCases,int resolvedCasesWithDisposition,int dispositionCoveragePercent,int withinWorkingHoursPercent){}
}
